PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0', "customer_column_order" text);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "configurator_products" ("id" integer primary key autoincrement not null, "handle" varchar not null, "category" varchar not null, "subtype" varchar, "title" varchar not null, "brand" varchar, "model" varchar, "year_from" integer, "year_to" integer, "option_name" varchar, "price_min" numeric, "image_url" text, "tags" text, "meta" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "configurator_variants" ("id" integer primary key autoincrement not null, "configurator_product_id" integer not null, "title" varchar, "sku" varchar, "option_value" varchar, "price" numeric, "image_url" text, "meta" text, "created_at" datetime, "updated_at" datetime, "shopify_variant_id" varchar, foreign key("configurator_product_id") references "configurator_products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "installation_zones" ("id" integer primary key autoincrement not null, "name" varchar not null, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "installation_zone_postal_codes" ("id" integer primary key autoincrement not null, "installation_zone_id" integer not null, "postal_code_from" varchar not null, "postal_code_to" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("installation_zone_id") references "installation_zones"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "installation_zone_products" ("id" integer primary key autoincrement not null, "installation_zone_id" integer not null, "product_handle" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("installation_zone_id") references "installation_zones"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "spanish_postal_codes" ("id" integer primary key autoincrement not null, "postal_code" varchar not null, "place_name" varchar, "province" varchar, "autonomous_community" varchar, "localities" text, "latitude" numeric not null, "longitude" numeric not null, "accuracy" integer, "source" varchar not null default 'GeoNames', "created_at" datetime, "updated_at" datetime, "island" varchar);
CREATE TABLE IF NOT EXISTS "quote_counters" ("id" integer primary key autoincrement not null, "quote_date" varchar not null, "last_number" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "missing_vehicle_requests" ("id" integer primary key autoincrement not null, "first_name" varchar not null, "last_name" varchar not null, "email" varchar not null, "phone" varchar not null, "province" varchar not null, "brand" varchar not null, "model" varchar not null, "year" integer not null, "comment" text, "photo_path" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "customers" ("id" integer primary key autoincrement not null, "shopify_id" varchar, "email" varchar, "first_name" varchar, "last_name" varchar, "phone" varchar, "language" varchar, "state" varchar, "note" text, "tags" text, "total_orders" integer not null default '0', "total_spent" numeric not null default '0', "shopify_created_at" datetime, "shopify_updated_at" datetime, "created_at" datetime, "updated_at" datetime, "first_order_at" datetime, "last_order_at" datetime, "attention_color" varchar);
CREATE TABLE IF NOT EXISTS "customer_addresses" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "shopify_id" varchar, "first_name" varchar, "last_name" varchar, "company" varchar, "phone" varchar, "line_1" varchar, "line_2" varchar, "city" varchar, "province" varchar, "province_code" varchar, "country" varchar, "country_code" varchar, "zip" varchar, "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_orders" ("id" integer primary key autoincrement not null, "customer_id" integer, "shopify_id" varchar not null, "name" varchar not null, "number" varchar, "processed_at" datetime, "shopify_created_at" datetime, "shopify_updated_at" datetime, "cancelled_at" datetime, "cancel_reason" varchar, "currency" varchar not null default 'EUR', "total_line_items" numeric not null default '0', "total_discount" numeric not null default '0', "total_shipping" numeric not null default '0', "total_refund" numeric not null default '0', "total_outstanding" numeric not null default '0', "current_total" numeric not null default '0', "total" numeric not null default '0', "payment_status" varchar, "fulfillment_status" varchar, "additional_details" text, "billing_address" text, "shipping_address" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "customer_order_lines" ("id" integer primary key autoincrement not null, "customer_order_id" integer not null, "shopify_id" varchar, "product_id" varchar, "product_handle" varchar, "variant_id" varchar, "title" varchar not null, "name" text, "variant_title" varchar, "sku" varchar, "quantity" integer not null default '0', "price" numeric not null default '0', "discount" numeric not null default '0', "total" numeric not null default '0', "vendor" varchar, "properties" text, "fulfillment_service" varchar, "fulfillment_status" varchar, "created_at" datetime, "updated_at" datetime, foreign key("customer_order_id") references "customer_orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_order_transactions" ("id" integer primary key autoincrement not null, "customer_order_id" integer not null, "shopify_id" varchar, "kind" varchar, "processed_at" datetime, "amount" numeric not null default '0', "currency" varchar, "status" varchar, "message" text, "gateway" varchar, "payment_method" varchar, "wallet" varchar, "is_test" tinyint(1) not null default '0', "error_code" varchar, "created_at" datetime, "updated_at" datetime, foreign key("customer_order_id") references "customer_orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_order_refunds" ("id" integer primary key autoincrement not null, "customer_order_id" integer not null, "shopify_id" varchar, "created_at_shopify" datetime, "note" text, "restock" tinyint(1) not null default '0', "restock_type" varchar, "restock_location" varchar, "created_at" datetime, "updated_at" datetime, foreign key("customer_order_id") references "customer_orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_order_fulfillments" ("id" integer primary key autoincrement not null, "customer_order_id" integer not null, "shopify_id" varchar, "status" varchar, "created_at_shopify" datetime, "updated_at_shopify" datetime, "tracking_company" varchar, "location" varchar, "shipment_status" varchar, "tracking_number" varchar, "tracking_url" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_order_id") references "customer_orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_costs" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "description" varchar not null, "amount" numeric not null, "created_at" datetime, "updated_at" datetime, "currency" varchar not null default 'EUR', "exchange_rate" numeric not null default '1', "amount_eur" numeric not null default '0', foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_supplier_refunds" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "description" varchar not null, "amount" numeric not null, "currency" varchar not null default 'EUR', "exchange_rate" numeric not null default '1', "amount_eur" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_contacts" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "type" varchar not null, "value" text not null, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "shared_configurations" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "configuration" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "configuration_statistics" ("id" integer primary key autoincrement not null, "session_uuid" varchar, "event_type" varchar not null, "brand" varchar, "model" varchar, "year" integer, "product_id" integer, "variant_id" integer, "product_title" varchar, "variant_title" varchar, "product_price" numeric, "installation_selected" tinyint(1) not null default '0', "installation_type" varchar, "camera_selected" tinyint(1) not null default '0', "postal_code" varchar, "service_zone" varchar, "language" varchar, "referrer" text, "utm_source" varchar, "utm_campaign" varchar, "device_type" varchar, "created_at" datetime, "updated_at" datetime, "product_type" varchar, "configuration_value" numeric);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "configurator_products_handle_unique" on "configurator_products" ("handle");
CREATE INDEX "configurator_products_category_index" on "configurator_products" ("category");
CREATE INDEX "configurator_products_subtype_index" on "configurator_products" ("subtype");
CREATE INDEX "configurator_products_brand_index" on "configurator_products" ("brand");
CREATE INDEX "configurator_products_model_index" on "configurator_products" ("model");
CREATE INDEX "configurator_products_year_from_index" on "configurator_products" ("year_from");
CREATE INDEX "configurator_products_year_to_index" on "configurator_products" ("year_to");
CREATE INDEX "configurator_variants_sku_index" on "configurator_variants" ("sku");
CREATE INDEX "configurator_variants_shopify_variant_id_index" on "configurator_variants" ("shopify_variant_id");
CREATE INDEX "installation_zone_postal_codes_postal_code_from_postal_code_to_index" on "installation_zone_postal_codes" ("postal_code_from", "postal_code_to");
CREATE UNIQUE INDEX "installation_zone_products_installation_zone_id_product_handle_unique" on "installation_zone_products" ("installation_zone_id", "product_handle");
CREATE INDEX "installation_zone_products_product_handle_index" on "installation_zone_products" ("product_handle");
CREATE UNIQUE INDEX "spanish_postal_codes_postal_code_unique" on "spanish_postal_codes" ("postal_code");
CREATE INDEX "spanish_postal_codes_province_index" on "spanish_postal_codes" ("province");
CREATE INDEX "spanish_postal_codes_autonomous_community_index" on "spanish_postal_codes" ("autonomous_community");
CREATE INDEX "spanish_postal_codes_island_index" on "spanish_postal_codes" ("island");
CREATE UNIQUE INDEX "quote_counters_quote_date_unique" on "quote_counters" ("quote_date");
CREATE UNIQUE INDEX "customers_shopify_id_unique" on "customers" ("shopify_id");
CREATE INDEX "customers_email_index" on "customers" ("email");
CREATE INDEX "customers_total_orders_index" on "customers" ("total_orders");
CREATE UNIQUE INDEX "customer_addresses_customer_id_shopify_id_unique" on "customer_addresses" ("customer_id", "shopify_id");
CREATE INDEX "customers_last_order_at_index" on "customers" ("last_order_at");
CREATE UNIQUE INDEX "customer_orders_shopify_id_unique" on "customer_orders" ("shopify_id");
CREATE INDEX "customer_orders_name_index" on "customer_orders" ("name");
CREATE INDEX "customer_orders_processed_at_index" on "customer_orders" ("processed_at");
CREATE INDEX "customer_orders_payment_status_index" on "customer_orders" ("payment_status");
CREATE INDEX "customer_orders_fulfillment_status_index" on "customer_orders" ("fulfillment_status");
CREATE INDEX "customer_order_lines_product_handle_index" on "customer_order_lines" ("product_handle");
CREATE INDEX "customer_order_lines_sku_index" on "customer_order_lines" ("sku");
CREATE INDEX "customer_contacts_type_index" on "customer_contacts" ("type");
CREATE UNIQUE INDEX "shared_configurations_uuid_unique" on "shared_configurations" ("uuid");
CREATE INDEX "configuration_statistics_dedup_index" on "configuration_statistics" ("session_uuid", "event_type", "created_at");
CREATE INDEX "configuration_statistics_event_type_index" on "configuration_statistics" ("event_type");
CREATE INDEX "configuration_statistics_product_type_index" on "configuration_statistics" ("product_type");
COMMIT;
